#!/usr/bin/env node
'use strict';

const path = require('node:path');
const {
  FILE_NAME,
  TodoError,
  loadTodos,
  saveTodos,
  addTodo,
  parseId,
  completeTodo,
  deleteTodo,
  formatTodos,
} = require('./todos');

const USAGE = `Usage:
  node index.js add "<text>"    Add a new todo
  node index.js list            List all todos
  node index.js complete <id>   Mark a todo as done
  node index.js delete <id>     Delete a todo
  node index.js help            Show this help`;

/** Validates the single <id> argument taken by `complete` and `delete`. */
function requireId(command, args) {
  if (args.length === 0) {
    throw new TodoError(`Missing todo id. Usage: node index.js ${command} <id>`);
  }
  if (args.length > 1) {
    throw new TodoError(`Too many arguments. Usage: node index.js ${command} <id>`);
  }
  return parseId(args[0]);
}

function main(argv, cwd) {
  const [command, ...args] = argv;
  const file = path.join(cwd, FILE_NAME);

  switch (command) {
    case 'add': {
      if (args.length === 0) {
        throw new TodoError('Missing todo text. Usage: node index.js add "<text>"');
      }
      const todos = loadTodos(file);
      // Unquoted words (`add Buy milk`) are joined rather than truncated.
      const todo = addTodo(todos, args.join(' '));
      saveTodos(file, todos);
      console.log(`Added todo #${todo.id}: ${todo.text}`);
      return 0;
    }

    case 'list': {
      const todos = loadTodos(file);
      console.log(todos.length === 0 ? 'No todos yet. Add one with: node index.js add "<text>"' : formatTodos(todos));
      return 0;
    }

    case 'complete': {
      const id = requireId(command, args);
      const todos = loadTodos(file);
      const { todo, alreadyCompleted } = completeTodo(todos, id);
      if (alreadyCompleted) {
        console.log(`Todo #${todo.id} is already completed: ${todo.text}`);
      } else {
        saveTodos(file, todos);
        console.log(`Completed todo #${todo.id}: ${todo.text}`);
      }
      return 0;
    }

    case 'delete': {
      const id = requireId(command, args);
      const todos = loadTodos(file);
      const todo = deleteTodo(todos, id);
      saveTodos(file, todos);
      console.log(`Deleted todo #${todo.id}: ${todo.text}`);
      return 0;
    }

    case 'help':
    case '--help':
    case '-h':
      console.log(USAGE);
      return 0;

    case undefined:
      console.error(`Error: Missing command.\n\n${USAGE}`);
      return 1;

    default:
      console.error(`Error: Unknown command "${command}".\n\n${USAGE}`);
      return 1;
  }
}

try {
  process.exitCode = main(process.argv.slice(2), process.cwd());
} catch (err) {
  if (!(err instanceof TodoError)) throw err;
  console.error(`Error: ${err.message}`);
  process.exitCode = 1;
}

