'use strict';

const { describe, it, beforeEach, afterEach } = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');

const {
  TodoError,
  loadTodos,
  saveTodos,
  addTodo,
  parseId,
  completeTodo,
  deleteTodo,
  formatTodos,
} = require('../todos');

function todo(id, text = `Todo ${id}`, completed = false) {
  return { id, text, completed, createdAt: '2026-01-01T00:00:00.000Z' };
}

describe('loadTodos / saveTodos', () => {
  let dir;
  let file;

  beforeEach(() => {
    dir = fs.mkdtempSync(path.join(os.tmpdir(), 'todo-unit-'));
    file = path.join(dir, 'todos.json');
  });

  afterEach(() => {
    fs.rmSync(dir, { recursive: true, force: true });
  });

  it('returns an empty list when the file does not exist', () => {
    assert.deepEqual(loadTodos(file), []);
  });

  it('returns an empty list when the file is blank', () => {
    fs.writeFileSync(file, '  \n');
    assert.deepEqual(loadTodos(file), []);
  });

  it('round-trips todos through the file', () => {
    const todos = [todo(1), todo(2, 'Done thing', true)];
    saveTodos(file, todos);
    assert.deepEqual(loadTodos(file), todos);
  });

  it('writes pretty-printed JSON and leaves no temp files behind', () => {
    saveTodos(file, [todo(1)]);
