mutate() {
  T=$(mktemp -d); cp -R "$SRC/index.js" "$SRC/todos.js" "$SRC/test" "$SRC/package.json" "$T/"
  perl -0pi -e "$2" "$T/$1"
  if cmp -s "$SRC/$1" "$T/$1"; then echo "NOT APPLIED: $3"; return; fi
  node --check "$T/$1" || { echo "SYNTAX ERROR: $3"; return; }
  fails=$(cd "$T" && node --test 2>&1 | awk '/^ℹ fail/{print $3}')
  echo "fail=$fails  <- $3"; rm -rf "$T"; }
mutate todos.js 's/todos\.reduce\(\(max, todo\) => Math\.max\(max, todo\.id\), 0\) \+ 1/todos.length + 1/' "id = length+1 (reuses ids)"
mutate todos.js "s/if \(raw\.trim\(\) === ''\) return \[\];//" "blank file crashes"
